using UnityEngine;

public class Match3Game : MonoBehaviour
{
    //affles table
    public Transform[] gridPositions;

    //jewel objects
    public GameObject[] jewels;

    //scor population
    public int scorePopulation = 0;

    //match counter
    public int matchCounter = 0;

    private Vector2Int currentNode;

    void Start()
    {
        // Initialize the grid positions
        for (int i = 0; i < gridPositions.Length; i++)
        {
            gridPositions[i].GetComponent<RectTransform>().localPosition = new Vector2(i * 100, 0);
        }
    }

    void Update()
    {
        // Update the match counter
        matchCounter += Time.deltaTime;

        // Check if a game over
        if (matchCounter >= 10 && scorePopulation >= 100)
        {
            Debug.Log("Game Over!");
            // Add game over logic here
        }
    }

    void OnMouseDown()
    {
        // Get the clicked grid position
        currentNode = GetGridPositionFromInput();

        if (currentNode.x >= 0 && currentNode.x < gridPositions.Length && currentNode.y >= 0)
        {
            // Swap the jewel at the clicked position
            SwapJewelAt(currentNode);
        }
    }

    // Function to get the coordinates of the clicked grid position
    Vector2Int GetGridPositionFromInput()
    {
        // Raycast from the mouse position
        Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition);
        RaycastHit hit;
        if (Physics.Raycast(ray, out hit, 1000f))
        {
            // Get the grid position from the clicked object
            Transform gridPosition = hit.transform.parent;
            int x = gridPositions.ToList().IndexOf(gridPosition);
            return new Vector2Int(x, hit.transform.position.y / 100);
        }
        return new Vector2Int(-1, -1);
    }

    // Function to swap the jewel at the given position
    void SwapJewelAt(Vector2Int position)
    {
        // Get the new jewel and the old jewel
        GameObject newJewel = jewels[Random.Range(0, jewels.Length)];
        GameObject oldJewel = gridPositions[position.x].GetComponent<Child>().GetComponent<Jewel>();

        // Swap the jewels
        gridPositions[position.x].GetComponent<Child>().GetComponent<Jewel>().jewelType = newJewel.GetComponent[Jewel>().jewelType;
        newJewel.GetComponent[Jewel>().jewelType = oldJewel.GetComponent[Jewel>().jewelType;

        // Check for matches
        CheckForMatches();
    }

    // Function to check if there are any matches
    void CheckForMatches()
    {
        // Iterate through the grid positions
        for (int i = 0; i < gridPositions.Length; i++)
        {
            // Check if the jewel at the current position is a match
            if (gridPositions[i].GetComponent<Child>().GetComponent<Jewel>().jewelType == jewels[0].GetComponent[Jewel>().jewelType)
            {
                // Remove the matched jewel
                gridPositions[i].GetComponent<Child>().GetComponent<Jewel>().jewelType = null;
                scorePopulation++;

                // Check if there are any other matches nearby
                CheckForNearbyMatches(i);
            }
        }
    }

    // Function to check for nearby matches
    void CheckForNearbyMatches(int position)
    {
        // Iterate through the nearby positions
        for (int x = -1; x <= 1; x++)
        {
            for (int y = -1; y <= 1; y++)
            {
                if (x == 0 && y == 0)
                    continue;

                // Get the nearby position
                Vector2Int nearbyPosition = new Vector2Int(position + x, position + y);

                // Check if the nearby position is within the grid
                if (nearbyPosition.x >= 0 && nearbyPosition.x < gridPositions.Length && nearbyPosition.y >= 0)
                {
                    // Check if the nearby jewel is a match
                    if (gridPositions[nearbyPosition.x].GetComponent<Child>().GetComponent<Jewel>().jewelType == gridPositions[position].GetComponent<Child>().GetComponent<Jewel>().jewelType)
                    {
                        // Remove the matched jewel
                        gridPositions[nearbyPosition.x].GetComponent<Child>().GetComponent<Jewel>().jewelType = null;
                        scorePopulation++;

                        // Check if there are any other matches nearby
                        CheckForNearbyMatches(nearbyPosition.x);
                    }
                }
            }
        }
    }
}
