Here is an example of a React component that implements autocomplete functionality without relying on other third-party packages:
```
import React, { useState, useEffect } from 'react';

const Autocomplete = ({ suggestions, onSelect }) => {
  const [inputValue, setInputValue] = useState('');
  const [suggestionsList, setSuggestionsList] = useState([]);
  const [activeSuggestion, setActiveSuggestion] = useState(0);

  useEffect(() => {
    const timer = setTimeout(() => {
      const filteredSuggestions = suggestions.filter((suggestion) => {
        return suggestion.toLowerCase().includes(inputValue.toLowerCase());
      });
      setSuggestionsList(filteredSuggestions);
    }, 500);

    return () => {
      clearTimeout(timer);
    };
  }, [inputValue, suggestions]);

  const handleInputChange = (event) => {
    setInputValue(event.target.value);
  };

  const handleKeydown = (event) => {
    switch (event.key) {
      case 'ArrowUp':
        setActiveSuggestion((activeSuggestion - 1 + suggestions.length) % suggestions.length);
        break;
      case 'ArrowDown':
        setActiveSuggestion((activeSuggestion + 1) % suggestions.length);
        break;
      case 'Enter':
        onSelect(suggestions[activeSuggestion]);
        break;
      default:
        break;
    }
  };

  const handleSuggestionClick = (suggestion) => {
    onSelect(suggestion);
  };

  return (
    <div>
      <input
        type="text"
        value={inputValue}
        onChange={handleInputChange}
        onKeyDown={handleKeydown}
        placeholder="Type to autocomplete..."
      />
      {suggestionsList.length > 0 && (
        <ul>
          {suggestionsList.map((suggestion, index) => (
            <li
              key={index}
              style={{
                backgroundColor: index === activeSuggestion ? '#f0f0f0' : '',
              }}
              onClick={() => handleSuggestionClick(suggestion)}
            >
              {suggestion}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Autocomplete;
```
